={{ (() => {
  const r = $json;

  const types = [
    'plan',
    'risk',
    'status',
    'milestone',
    'stakeholder_update'
  ];

  const names = {
    plan: 'PROJECT PLAN',
    risk: 'RISK ASSESSMENT',
    status: 'STATUS REPORT',
    milestone: 'MILESTONE TRACKER',
    stakeholder_update: 'STAKEHOLDER UPDATE'
  };

  const text = (v) => {
    if (v === null || v === undefined || v === '') return 'Not provided';
    if (typeof v === 'string') return v;
    if (typeof v === 'number' || typeof v === 'boolean') return String(v);
    return JSON.stringify(v);
  };

  const list = (v) => {
    if (v === null || v === undefined || v === '') return [];
    return Array.isArray(v) ? v : [v];
  };

  const lines = [];

  const heading = (s) => {
    lines.push('', '## ' + s, '');
  };

  const field = (label, value) => {
    if (value !== null && value !== undefined && value !== '') {
      lines.push('**' + label + ':** ' + text(value));
    }
  };

  const items = (title, value) => {
    const arr = list(value);
    if (!arr.length) return;

    heading(title);

    for (const v of arr) {
      if (typeof v === 'string') {
        lines.push('- ' + v);
      } else if (v && typeof v === 'object') {
        const titleText =
          v.name ?? v.title ?? v.description ??
          v.risk_name ?? v.milestone_name ??
          v.task_name ?? v.task_id ?? v.id;

        if (titleText) {
          lines.push('- **' + text(titleText) + '**');
        }

        for (const [k, val] of Object.entries(v)) {
          if (val === null || val === undefined || val === '') continue;
          if (['name', 'title', 'description'].includes(k) && titleText === val) continue;

          if (typeof val === 'object') {
            lines.push('  - ' + k.replace(/_/g, ' ') + ': ' + JSON.stringify(val));
          } else {
            lines.push('  - ' + k.replace(/_/g, ' ') + ': ' + text(val));
          }
        }

        if (!titleText && Object.keys(v).length === 0) {
          lines.push('- Empty record');
        }
      } else {
        lines.push('- ' + text(v));
      }
    }
  };

  const formattedText = (d) => {
    const candidates = [
      d.report_markdown,
      d.markdown,
      d.report?.report_markdown,
      d.report?.markdown,
      d.formatted_report,
      d.report_text,
      d.content_markdown
    ];

    return candidates.find(
      v => typeof v === 'string' && v.trim() !== ''
    );
  };

  const renderStatus = (d) => {
    field('Reporting period', d.report_period);
    field('Overall RAG', d.overall_rag);

    heading('Executive Summary');
    lines.push(text(d.executive_summary));

    const tasks = list(d.tasks);

    if (tasks.length) {
      heading('Task Progress');

      const counts = {
        'Done': 0,
        'In Progress': 0,
        'To Do': 0,
        'Blocked': 0,
        'Other': 0
      };

      for (const t of tasks) {
        const s = String(t.status ?? '').trim();

        if (['Done', 'In Progress', 'To Do', 'Blocked'].includes(s)) {
          counts[s]++;
        } else {
          counts.Other++;
        }
      }

      lines.push(
        '- Total task records: ' + tasks.length,
        '- Completed: ' + counts.Done,
        '- In progress: ' + counts['In Progress'],
        '- To do: ' + counts['To Do'],
        '- Blocked: ' + counts.Blocked
      );

      if (counts.Other) {
        lines.push('- Other/unknown: ' + counts.Other);
      }

      if (d.total_tasks !== undefined &&
          Number(d.total_tasks) !== tasks.length) {
        lines.push(
          '**COUNT WARNING:** Reported total ' +
          d.total_tasks + ' differs from ' +
          tasks.length + ' task records.'
        );
      }

      items('Task Details', tasks);
    } else {
      field('Reported total tasks', d.total_tasks);
      if (d.task_counts) items('Reported Task Counts', d.task_counts);
    }

    items('Workstreams', d.workstreams);
    items('Highlights', d.highlights);
    items('Upcoming Work', d.upcoming);
    items('Issues and Blockers', d.issues_and_blockers);
    items('Risks', d.risks);

    if (d.email_draft) {
      heading('Stakeholder Email — DRAFT');
      field('Subject', d.email_draft.subject);
      lines.push('', text(d.email_draft.body));
    }
  };

  const renderPlan = (d) => {
    const p = d.plan && typeof d.plan === 'object'
      ? d.plan : d;

    field('Project', p.project_name ?? p.name);
    field('Duration', p.duration ?? p.project_duration);
    field('Summary', p.summary ?? p.executive_summary);

    items('Objectives', p.objectives ?? p.project_objectives);
    items('Scope', p.scope ?? p.in_scope);
    items('Phases', p.phases ?? p.project_phases);
    items('Work Breakdown', p.work_breakdown ?? p.workstreams);
    items('Activities', p.activities ?? p.tasks);
    items('Milestones', p.milestones);
    items('Dependencies', p.dependencies);
    items('Deliverables', p.deliverables);
    items('Assumptions', p.assumptions);
    items('Constraints', p.constraints);
  };

  const renderRisk = (d) => {
    const p = d.risk_assessment && typeof d.risk_assessment === 'object'
      ? d.risk_assessment : d;

    field('Overall risk level', p.overall_risk_level ?? p.overall_risk);
    field('Summary', p.executive_summary ?? p.summary);

    items('Risk Register',
      p.risks ?? p.risk_register ?? p.identified_risks);

    items('High Priority Risks', p.high_priority_risks);
    items('Mitigation Actions', p.mitigation_actions);
    items('Dependencies', p.dependencies);
    items('Recommendations', p.recommendations);
  };

  const renderMilestone = (d) => {
    const p = d.milestone_report && typeof d.milestone_report === 'object'
      ? d.milestone_report : d;

    field('Reporting period', p.report_period);
    field('Overall milestone status', p.overall_status);
    field('Summary', p.executive_summary ?? p.summary);

    items('Milestones', p.milestones ?? p.milestone_statuses);
    items('Upcoming Milestones', p.upcoming_milestones);
    items('Completed Milestones', p.completed_milestones);
    items('Delayed Milestones', p.delayed_milestones);
    items('Dependencies', p.dependencies);
    items('Blockers', p.blockers);
    items('Recommendations', p.recommendations);
  };

  const renderStakeholder = (d) => {
    const p = d.stakeholder_update &&
      typeof d.stakeholder_update === 'object'
      ? d.stakeholder_update : d;

    field('Audience', p.audience ?? p.target_audience);
    field('Reporting period', p.report_period);
    field('Subject', p.subject);

    heading('Executive Summary');
    lines.push(text(p.executive_summary ?? p.summary));

    items('Key Messages', p.key_messages);
    items('Progress Highlights', p.highlights);
    items('Decisions Required', p.decisions_required);
    items('Risks and Issues', p.risks_and_issues);
    items('Next Steps', p.next_steps);

    const draft = p.email_draft ?? p.draft;

    if (draft) {
      heading('Communication — DRAFT');

      if (typeof draft === 'string') {
        lines.push(draft);
      } else {
        field('Subject', draft.subject);
        lines.push('', text(draft.body ?? draft.message));
      }
    }
  };

  const renderUnknownFields = (d, usedKeys) => {
    if (!d || typeof d !== 'object') return;

    const metadata = [
      'agent', 'snapshot_id', 'trace_id',
      'span_id', 'generated_at', 'status',
      'validation_status', 'task_counts_validated'
    ];

    const extra = Object.keys(d).filter(
      k => !usedKeys.includes(k) && !metadata.includes(k)
    );

    if (extra.length) {
      heading('Additional Report Data');

      for (const k of extra) {
        const v = d[k];
        if (v === null || v === undefined || v === '') continue;

        lines.push(
          '**' + k.replace(/_/g, ' ') + ':**',
          typeof v === 'string' ? v : '```json\n' +
          JSON.stringify(v, null, 2) + '\n```',
          ''
        );
      }
    }
  };

  if (['needs_clarification', 'insufficient_data', 'error'].includes(r.status)) {
    return r.message || 'Mira could not complete the request.';
  }

  const reports = r.reports || {};
  const available = types.filter(k => reports[k] != null);

  if (!available.length) {
    return 'Mira returned no report.\n' +
      'Execution: ' + text(r.status) + '\n' +
      'Run ID: ' + text(r.run_id) + '\n' +
      'Snapshot: ' + text(r.snapshot_id);
  }


  lines.push(
    '# MIRA PROJECT INTELLIGENCE — DRAFT',
    '',
    '**Execution:** ' + text(r.status),
    '**Overall validation:** ' + text(r.overall_validation ?? 'NOT_REPORTED'),
    '**Snapshot:** ' + text(r.snapshot_id),
    '**Run ID:** ' + text(r.run_id),
    '**Reports returned:** ' + available.length,
    ''
  );

  for (const type of available) {
    const d = reports[type];

    lines.push(
      '',
      '---',
      '',
      '# ' + names[type],
      ''
    );

    if (!d || typeof d !== 'object') {
      lines.push(text(d));
      continue;
    }



    const validation =
      d.validation_status ??
      r.validation?.[type]?.validation_status ??
      r.overall_validation ??
      'NOT_REPORTED';

    field('Report validation', validation);
if (
  d.validation_status &&
  r.validation?.[type]?.validation_status &&
  String(d.validation_status).toLowerCase() !==
  String(r.validation[type].validation_status).toLowerCase()
) {
  lines.push(
    '**Validation discrepancy:** Agent reports ' +
    d.validation_status +
    ', while Orchestrator reports ' +
    r.validation[type].validation_status
  );
}
    field('Generated at', d.generated_at);

    // Compare agent and Orchestrator validation results
    const agentValidation = d.validation_status;
    const validatorResult =
      r.validation?.[type]?.validation_status;

    if (
      agentValidation &&
      validatorResult &&
      String(agentValidation).toLowerCase() !==
      String(validatorResult).toLowerCase()
    ) {
      lines.push(
        '',
        '**Validation discrepancy:** Agent reports ' +
        agentValidation +
        ', while the Orchestrator validator reports ' +
        validatorResult +
        '.',
        ''
      );
    }

    const formatted = formattedText(d);

    if (formatted) {
      lines.push('', formatted);
    } else if (type === 'status') {
      renderStatus(d);
    } else if (type === 'plan') {
      renderPlan(d);
    } else if (type === 'risk') {
      renderRisk(d);
    } else if (type === 'milestone') {
      renderMilestone(d);
    } else if (type === 'stakeholder_update') {
      renderStakeholder(d);
    }

    items('Data Gaps', d.data_gaps);
    items('Source References', d.source_references);

    // Preserve any schema fields not explicitly formatted.
    // This prevents silent loss of report information.
    if (!formatted && type !== 'status') {
      lines.push(
        '',
        '<details>',
        '<summary>Complete structured report data</summary>',
        '',
        '```json',
        JSON.stringify(d, null, 2),
        '```',
        '</details>'
      );
    }
  }

  return lines.join('\n');
})() }}

