        "enum": [
          "plan",
          "risk",
          "status",
          "milestone",
          "stakeholder_update"
        ]
      },
      "description": "Requested report capabilities."
    },
    "message": {
      "type": "string",
      "description": "Clarification or error. Empty when selected."
