parameters.jsCode:
const items = $input.all();

const orchestrator = $(
  "Call 'Mira_00_Orchestrator'"
).first().json;

const supportedCapabilities = [
  'plan',
  'risk',
  'status',
  'milestone',
  'stakeholder_update'
];

const reports = orchestrator.reports ?? {};

const requestedCapabilities =
  supportedCapabilities.filter(type =>
    reports[type] !== undefined &&
    reports[type] !== null
  );

const capability =
  requestedCapabilities.length === 1
    ? requestedCapabilities[0]
    : requestedCapabilities.length > 1
      ? 'multi'
      : 'unknown';

const seen = new Set();
const results = [];

for (const item of items) {
  const data = item.json || {};

  const runId = String(data.run_id ?? '');
  const snapshotId = String(data.snapshot_id ?? '');
  const validation = String(
    data.validation_status ?? ''
  ).toLowerCase();

  const execution = String(
    data.execution_status ?? ''
  ).toLowerCase();

  const report = String(data.output ?? '');

  // Do not submit failed reports for approval.
  if (
    execution !== 'ok' ||
    validation !== 'passed' ||
    !report.trim()
  ) {
    continue;
  }

  // Prevent duplicate requests for the same run
  // within this execution.
  const key = `${snapshotId}:${runId}`;

  if (seen.has(key)) continue;
  seen.add(key);


results.push({
  json: {
    request_id: key,
    run_id: runId,
    snapshot_id: snapshotId,    
capability: capability,
requested_capabilities: requestedCapabilities,


    project_name: 'ABCDE Ltd AI Adoption',

    reviewer_email: 'REVIEWER_EMAIL_PLACEHOLDER',

    report_title: 'MIRA Project Intelligence Report',
    report_content: report,
    review_type: 'report',
    approval_status: 'PENDING',
    draft_only: true
  }
});

}

return results;

