{{ (() => {
  const type = String($json.Type ?? '').toLowerCase();

  if (type.startsWith('plan')) return 'plan';
  if (type.startsWith('risk')) return 'risk';
  if (type.startsWith('status')) return 'status';
  if (type.startsWith('tracking') || type.startsWith('timeline'))
    return 'milestone';
  if (type.startsWith('comms')) return 'stakeholder_update';

  return 'unknown';
})() }}
